// Builds what the npm package ships: lib/index.js (src/ with packages/core bundled in; dsh and the RushDB libraries
// stay external, resolved from the dsh profile) and icon.png (a copy of shared/assets/icon.png).
import { copyFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'esbuild'

export const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..')

const BANNER = [
  '// @rushdb/dsh: RushDB for DeepSeek Harness.',
  '// GENERATED by packages/dsh/scripts/build.ts from packages/dsh and packages/core; do not edit. Source:',
  '// https://github.com/rush-db/agent-plugins (Apache-2.0).'
].join('\n')

/** Writes lib/index.js and icon.png into the package and returns the bundle's path. */
export async function buildPackage(root = packageRoot): Promise<string> {
  const outfile = join(root, 'lib', 'index.js')
  await build({
    absWorkingDir: root,
    entryPoints: [join(root, 'src', 'index.ts')],
    outfile,
    bundle: true,
    platform: 'node',
    format: 'esm',
    target: 'node22',
    minify: false,
    sourcemap: false,
    legalComments: 'inline',
    charset: 'utf8',
    banner: { js: BANNER },
    external: ['@deepseek-ai/*', '@rushdb/agent-memory-contract', '@rushdb/javascript-sdk'],
    logLevel: 'warning'
  })
  await copyFile(join(root, '..', '..', 'shared', 'assets', 'icon.png'), join(root, 'icon.png'))
  return outfile
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  console.log(`wrote ${await buildPackage()}`)
}
